<?php
/**
 * NyaaXport Cloud — API product exporter for Shopify, BigCommerce, Wix,
 * Prom.ua and Horoshop. Author: Yevhen Levchenko.
 * PHP 7.0–8.x, cURL required. Credentials are never written to disk.
 */
if(PHP_VERSION_ID<70000||PHP_VERSION_ID>=90000){http_response_code(500);exit('PHP 7.x or 8.x required.');}
const NYAAXPORT_CLOUD_KEY='CHANGE-ME-NOW';
session_name('nyaaxport_cloud');session_start();
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function xv($v){return htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function av($a,$k,$d=''){return is_array($a)&&isset($a[$k])?$a[$k]:$d;}
function pathv($a,$path,$d=''){foreach(explode('.',$path) as $k){if(!is_array($a)||!isset($a[$k]))return $d;$a=$a[$k];}return $a;}
function plain($v){return trim(preg_replace('/\s+/u',' ',html_entity_decode(strip_tags((string)$v),ENT_QUOTES|ENT_HTML5,'UTF-8')));}
if(!isset($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
function csrf(){return '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">';}
function csrfOk(){return isset($_POST['csrf'])&&hash_equals($_SESSION['csrf'],(string)$_POST['csrf']);}
if(isset($_POST['logout'])&&csrfOk()){session_destroy();header('Location: '.strtok($_SERVER['REQUEST_URI'],'?'));exit;}
if(isset($_POST['access_key'])&&csrfOk()&&NYAAXPORT_CLOUD_KEY!=='CHANGE-ME-NOW'&&hash_equals(NYAAXPORT_CLOUD_KEY,(string)$_POST['access_key']))$_SESSION['ok']=1;
$ok=!empty($_SESSION['ok']);

function apiRequest($method,$url,$headers=[],$body=null){
    if(!extension_loaded('curl'))throw new RuntimeException('PHP cURL extension is required.');
    $ch=curl_init($url);$responseHeaders=[];
    curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>90,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_HEADERFUNCTION=>function($ch,$line)use(&$responseHeaders){$p=strpos($line,':');if($p!==false)$responseHeaders[strtolower(trim(substr($line,0,$p)))]=trim(substr($line,$p+1));return strlen($line);}]);
    if($body!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,is_string($body)?$body:json_encode($body));
    $raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);
    if($raw===false||$err!=='')throw new RuntimeException('API connection error: '.$err);
    $json=json_decode($raw,true);if($code<200||$code>=300)throw new RuntimeException('API HTTP '.$code.': '.substr(plain($raw),0,500));
    if(!is_array($json))throw new RuntimeException('API returned invalid JSON.');return [$json,$responseHeaders];
}
function row($id,$name,$sku,$url,$price,$sale,$currency,$qty,$status,$brand,$category,$description,$image,$barcode='',$modified=''){return ['id'=>$id,'name'=>$name,'sku'=>$sku,'url'=>$url,'price'=>$price,'special_price'=>$sale,'currency'=>$currency,'quantity'=>$qty,'status'=>$status,'manufacturer'=>$brand,'category'=>$category,'description'=>plain($description),'image'=>$image,'barcode'=>$barcode,'date_modified'=>$modified];}

function shopifyRows($domain,$token){
    $domain=preg_replace('~^https?://~','',trim($domain));$domain=rtrim($domain,'/');$cursor=null;
    do{$query='query Products($after:String){products(first:100,after:$after){pageInfo{hasNextPage endCursor}nodes{id title descriptionHtml handle onlineStoreUrl vendor productType updatedAt featuredMedia{preview{image{url}}}variants(first:100){nodes{id sku price compareAtPrice inventoryQuantity barcode image{url}}}}}}';
        list($j)=apiRequest('POST','https://'.$domain.'/admin/api/2026-07/graphql.json',['Content-Type: application/json','X-Shopify-Access-Token: '.$token],['query'=>$query,'variables'=>['after'=>$cursor]]);
        if(isset($j['errors']))throw new RuntimeException('Shopify: '.json_encode($j['errors']));$data=pathv($j,'data.products',[]);
        foreach(av($data,'nodes',[]) as $p){$variants=pathv($p,'variants.nodes',[]);if(!$variants)$variants=[[]];foreach($variants as $v){$gid=av($v,'id',av($p,'id'));$id=substr($gid,strrpos($gid,'/')+1);$url=av($p,'onlineStoreUrl','');if($url==='')$url='https://'.$domain.'/products/'.av($p,'handle');yield row($id,av($p,'title'),av($v,'sku'),$url,av($v,'price'),av($v,'compareAtPrice'),'',$v?av($v,'inventoryQuantity',0):0,1,av($p,'vendor'),av($p,'productType'),av($p,'descriptionHtml'),pathv($v,'image.url',pathv($p,'featuredMedia.preview.image.url','')),av($v,'barcode'),av($p,'updatedAt'));}}
        $cursor=pathv($data,'pageInfo.endCursor',null);$more=(bool)pathv($data,'pageInfo.hasNextPage',false);
    }while($more);
}
function bigCommerceRows($hash,$token,$domain=''){
    $page=1;do{list($j)=apiRequest('GET','https://api.bigcommerce.com/stores/'.rawurlencode($hash).'/v3/catalog/products?include=variants,images,primary_image&limit=250&page='.$page,['Accept: application/json','X-Auth-Token: '.$token]);$items=av($j,'data',[]);
        foreach($items as $p){$variants=av($p,'variants',[]);if(!$variants)$variants=[[]];foreach($variants as $v){$id=av($v,'id',av($p,'id'));$custom=av($p,'custom_url',[]);$url=$domain!==''?rtrim($domain,'/').av($custom,'url',''):'';$img=pathv($p,'primary_image.url_standard','');yield row($id,av($p,'name'),av($v,'sku',av($p,'sku')),$url,av($v,'price',av($p,'price')),av($v,'sale_price',av($p,'sale_price')),av($p,'currency',''),av($v,'inventory_level',av($p,'inventory_level',0)),av($p,'is_visible',1),av($p,'brand_name',''),implode(', ',av($p,'categories',[])),av($p,'description'),$img,av($v,'upc',av($p,'upc')),av($p,'date_modified'));}}
        $pages=(int)pathv($j,'meta.pagination.total_pages',1);$page++;
    }while($page<=$pages);
}
function promRows($token){$last=0;do{list($j)=apiRequest('GET','https://my.prom.ua/api/v1/products/list?limit=100&last_id='.$last,['Authorization: Bearer '.$token]);$items=av($j,'products',[]);foreach($items as $p){$last=max($last,(int)av($p,'id'));$images=av($p,'images',[]);yield row(av($p,'id'),av($p,'name'),av($p,'sku'),av($p,'url'),av($p,'price'),'',av($p,'currency'),av($p,'quantity_in_stock',0),av($p,'status')==='on_display',av($p,'manufacturer'),av($p,'category'),av($p,'description'),isset($images[0])?av($images[0],'url'):'' );}}while(count($items)===100);}
function wixRows($token,$siteId){$skip=0;do{list($j)=apiRequest('POST','https://www.wixapis.com/stores/v1/products/query',['Content-Type: application/json','Authorization: '.$token,'wix-site-id: '.$siteId],['query'=>['paging'=>['limit'=>100,'offset'=>$skip]]]);$items=av($j,'products',[]);foreach($items as $p){$variants=pathv($p,'variants',[]);if(!$variants)$variants=[[]];foreach($variants as $v)yield row(av($v,'id',av($p,'id')),av($p,'name'),av($v,'sku'),av($p,'productPageUrl'),pathv($v,'priceData.price',pathv($p,'priceData.price','')),pathv($v,'priceData.discountedPrice',''),pathv($p,'priceData.currency',''),av($v,'quantity',0),av($p,'visible',1),av($p,'brand'),'',av($p,'description'),pathv($p,'media.mainMedia.image.url',''),av($v,'barcode'),av($p,'lastUpdatedDate'));}$skip+=count($items);}while(count($items)===100);}
function genericRows($endpoint,$token){list($j)=apiRequest('GET',$endpoint,$token!==''?['Authorization: Bearer '.$token]:[]);$items=av($j,'products',av($j,'data',$j));foreach($items as $p)yield row(av($p,'id',av($p,'product_id')),av($p,'name',av($p,'title')),av($p,'sku',av($p,'article')),av($p,'url'),av($p,'price'),av($p,'special_price',av($p,'sale_price')),av($p,'currency'),av($p,'quantity',av($p,'stock',0)),av($p,'status',1),av($p,'brand',av($p,'manufacturer')),av($p,'category'),av($p,'description'),av($p,'image',av($p,'image_url')),av($p,'barcode'),av($p,'updated_at'));}

function fields(){return ['id'=>'ID','name'=>'Name','sku'=>'SKU','url'=>'URL','price'=>'Price','special_price'=>'Sale price','currency'=>'Currency','quantity'=>'Quantity','status'=>'Status','manufacturer'=>'Manufacturer','category'=>'Category','description'=>'Description','image'=>'Image','barcode'=>'Barcode','date_modified'=>'Modified'];}
function safe($v){$v=(string)$v;if($v!==''&&in_array($v[0],['=','+','-','@'],true))$v="'".$v;return $v;}
function headersOut($format){$ext=$format==='xls'?'xls':$format;header('Content-Type: '.($format==='csv'?'text/csv; charset=UTF-8':($format==='xml'?'application/xml; charset=UTF-8':'application/vnd.ms-excel')));header('Content-Disposition: attachment; filename="cloud_products_'.date('Y-m-d_H-i-s').'.'.$ext.'"');header('Cache-Control: no-store');}
function exportRows($rows,$format){$f=fields();if($format==='csv'){echo "\xEF\xBB\xBF";$o=fopen('php://output','wb');fputcsv($o,array_values($f),';');foreach($rows as $r){$x=[];foreach($f as $k=>$l)$x[]=safe(av($r,$k));fputcsv($o,$x,';');}fclose($o);}elseif($format==='xml'){echo '<?xml version="1.0" encoding="UTF-8"?><products>';foreach($rows as $r){echo '<product>';foreach($f as $k=>$l)echo '<'.$k.'>'.xv(av($r,$k)).'</'.$k.'>';echo '</product>';}echo '</products>';}else{echo "\xEF\xBB\xBF".'<meta charset="UTF-8"><table border="1"><tr>';foreach($f as $l)echo '<th>'.h($l).'</th>';echo '</tr>';foreach($rows as $r){echo '<tr>';foreach($f as $k=>$l)echo '<td>'.h(safe(av($r,$k))).'</td>';echo '</tr>';}echo '</table>';}}

$error=null;if($ok&&isset($_POST['export']))try{if(!csrfOk())throw new RuntimeException('Invalid security token.');@set_time_limit(0);$provider=av($_POST,'provider');$token=trim(av($_POST,'token'));if($token==='')throw new RuntimeException('API token is required.');if($provider==='shopify')$rows=shopifyRows(av($_POST,'domain'),$token);elseif($provider==='bigcommerce')$rows=bigCommerceRows(av($_POST,'store_hash'),$token,av($_POST,'domain'));elseif($provider==='prom')$rows=promRows($token);elseif($provider==='wix')$rows=wixRows($token,av($_POST,'site_id'));else $rows=genericRows(av($_POST,'endpoint'),$token);$format=av($_POST,'format','csv');if(!in_array($format,['csv','xml','xls'],true))throw new RuntimeException('Unknown format.');headersOut($format);exportRows($rows,$format);exit;}catch(Exception $e){$error=$e->getMessage();}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NyaaXport Cloud</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f3ff;color:#1e1b4b;font:15px/1.5 system-ui,sans-serif}.wrap{max-width:900px;margin:42px auto;padding:16px}.card,.support{background:#fff;border:1px solid #ddd6fe;border-radius:18px;padding:26px;margin-bottom:22px;box-shadow:0 14px 45px #312e8112}h1{margin:0}.muted{color:#6b7280}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:20px 0}label{font-weight:700}input,select{display:block;width:100%;margin-top:5px;padding:11px;border:1px solid #c4b5fd;border-radius:9px}button{padding:12px 18px;border:0;border-radius:10px;background:#4f46e5;color:#fff;font-weight:800}.error,.warning{padding:12px;border-radius:9px;margin:15px 0}.error{background:#fee2e2;color:#991b1b}.warning{background:#fffbeb;color:#92400e}.support table{width:100%;border-collapse:collapse}.support td,.support th{text-align:left;padding:8px;border-bottom:1px solid #eee}.support td:last-child{font-family:monospace;overflow-wrap:anywhere}@media(max-width:600px){.support td,.support th{display:block}}</style></head><body><main class="wrap"><section class="card"><h1>NyaaXport Cloud</h1><p class="muted">Shopify · BigCommerce · Wix · Prom.ua · Horoshop / custom JSON API</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><?php if(!$ok):?><form method="post"><?=csrf()?><label>Ключ доступа<input type="password" name="access_key" required></label><p><button>Открыть</button></p></form><?php if(NYAAXPORT_CLOUD_KEY==='CHANGE-ME-NOW'):?><div class="warning">Замените CHANGE-ME-NOW в начале файла перед загрузкой на сервер.</div><?php endif;?><?php else:?><form method="post"><?=csrf()?><div class="grid"><label>Платформа<select name="provider" id="provider"><option value="shopify">Shopify</option><option value="bigcommerce">BigCommerce</option><option value="wix">Wix</option><option value="prom">Prom.ua</option><option value="horoshop">Horoshop / JSON API</option></select></label><label>API token<input type="password" name="token" required autocomplete="off"></label><label>Домен магазина<input name="domain" placeholder="store.myshopify.com"></label><label>BigCommerce store hash<input name="store_hash"></label><label>Wix site ID<input name="site_id"></label><label>Horoshop / JSON endpoint<input type="url" name="endpoint" placeholder="https://example.com/api/products"></label><label>Формат<select name="format"><option value="csv">CSV</option><option value="xml">XML</option><option value="xls">XLS</option></select></label></div><div class="warning">Токен передаётся непосредственно API выбранной платформы и не сохраняется на сервере.</div><button name="export" value="1">Скачать товары</button></form><form method="post" style="margin-top:12px"><?=csrf()?><button name="logout" value="1">Выйти</button></form><?php endif;?></section><footer class="support"><h2>Поддержать проект</h2><p>Если NyaaXport оказался полезен, вы можете поддержать дальнейшую разработку:</p><table><tr><th>Сеть</th><th>Адрес</th></tr><tr><td>USDT — TRC20</td><td>TR3fkALFRTDyRaHsDU8aUmANGPRDy2gU1s</td></tr><tr><td>ETH — ERC20</td><td>0x9d20248c779dcb742f7795a0c7461346c0c8934e</td></tr><tr><td>BTC</td><td>1BQwypiKfhNGb1ryKzdp7TBPL4wR6ckU4J</td></tr><tr><td>PayPal</td><td><a href="mailto:spirt51@hotmail.com">spirt51@hotmail.com</a></td></tr></table><div class="warning">Перед переводом криптовалюты обязательно проверьте выбранную сеть и адрес.</div><p class="muted">NyaaXport · Yevhen Levchenko</p></footer></main></body></html>
